// Backfill STATS: page POST /admin/stats-rebuild on the live Worker
// until every listed record has a record_stats row. Same operator
// pattern as scripts/backfill-embed.mjs: the admin token is read
// in-process from /tmp/talents-admin-token (generated by
// cf/scripts/set_discovery_secrets.py, 0600, never printed, never
// filed in the repo); the route is PAGED (limit + cursor, one
// bounded page per call); the cursor only advances on an HTTP 200
// page; a failed page retries with backoff and halves the page
// size after repeated failures.
//
// The catalog grows while the loop runs (queue + drain ingests), so
// after a sweep reports done, coverage is judged on the last page's
// statsRows vs listed counts: records ingested during the sweep get
// stats from ingestSource's incremental update, so one full sweep
// should already converge. A second sweep runs only if the counts
// still disagree. Restart-safe and idempotent throughout (the
// route recomputes every page it visits).
//
// Usage: node scripts/stats-rebuild-run.mjs [--limit N] [--max-pages N] [--max-sweeps N]
import { readFileSync } from "node:fs";

const args = process.argv.slice(2);
const argNum = (name, dflt) => (args.includes(name) ? Number(args[args.indexOf(name) + 1]) : dflt);
const maxPages = argNum("--max-pages", 600);
const maxSweeps = argNum("--max-sweeps", 4);
let pageSize = argNum("--limit", 500);
const token = readFileSync("/tmp/talents-admin-token", "utf8").trim();

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function callPage(cursor) {
  let failures = 0;
  for (;;) {
    let status = 0, body = {};
    try {
      const res = await fetch("https://talents.sh/admin/stats-rebuild", {
        method: "POST",
        headers: { "content-type": "application/json", "x-talents-admin": token },
        body: JSON.stringify({ limit: pageSize, cursor }),
        signal: AbortSignal.timeout(120_000),
      });
      status = res.status;
      body = await res.json().catch(() => ({}));
    } catch (e) {
      body = { error: `network: ${e.message}` };
    }
    if (status === 200) return { body, retries: failures };
    failures++;
    if (failures % 6 === 0 && pageSize > 25) {
      pageSize = Math.max(25, Math.floor(pageSize / 2));
      console.log(`page at cursor=${cursor}: ${failures} failures — halving page size to ${pageSize}`);
    }
    const wait = Math.min(30_000, 5_000 * failures);
    console.log(`page at cursor=${cursor}: HTTP ${status} ${JSON.stringify(body).slice(0, 120)} — retry ${failures} in ${wait / 1000}s`);
    if (failures >= 40) return { body: null, retries: failures };
    await sleep(wait);
  }
}

let cursor = null;
let pages = 0, totalProcessed = 0, totalRetries = 0, sweeps = 0;
let gaveUp = false;
let lastStatsRows = 0, lastListed = 0;
const started = Date.now();
while (pages < maxPages && sweeps < maxSweeps) {
  const { body, retries } = await callPage(cursor);
  totalRetries += retries;
  if (!body) { gaveUp = true; break; }
  pages++;
  totalProcessed += body.processed ?? 0;
  lastStatsRows = body.statsRows ?? lastStatsRows;
  lastListed = body.listed ?? lastListed;
  console.log(`sweep ${sweeps + 1} page ${pages}: processed=${body.processed} done=${body.done} statsRows=${body.statsRows} listed=${body.listed} (totals: processed ${totalProcessed}, retries ${totalRetries})`);
  if (body.done) {
    sweeps++;
    if (lastStatsRows >= lastListed) break;
    console.log(`coverage gap after sweep ${sweeps}: statsRows=${lastStatsRows} listed=${lastListed} — starting another sweep`);
    cursor = null;
    continue;
  }
  cursor = body.nextCursor;
}
console.log(JSON.stringify({
  pages, totalProcessed, totalRetries, sweeps, gaveUp,
  finalStatsRows: lastStatsRows, finalListed: lastListed,
  elapsedMs: Date.now() - started,
}));
